fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    use std::collections::HashMap;

    let mut index_map = HashMap::new();

    for (i, &num) in nums.iter().enumerate() {
        // Calculate the complement
        let complement = target - num;

        // Check for overflow
        if (num > 0 && complement < std::i32::MIN + num) || (num < 0 && complement > std::i32::MAX + num) {
            continue; // Skip this pair as it would overflow
        }

        // Check if the complement exists in the map
        if let Some(&j) = index_map.get(&complement) {
            // Ensure indices are distinct and in the correct order
            if i != j {
                return Some((j.min(i), j.max(i))); // Return the lexicographically smallest pair
            }
        }

        // Store the index of the current number
        index_map.insert(num, i);
    }

    None // Return None if no valid pair is found
}